# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено по определению следствия; условия сверены с текстом учебника (№14.19)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_14_2_14_19_b", r"возведение в квадрат даёт систему-следствие: каждое решение первой системы ($\sqrt{x+1}=y-x$) удовлетворяет $x+1=(y-x)^{2}$; обратное неверно; в ключе стояло «нет»",
  k="да",
  dnew={0: ("нет", "Ученик решил, что возведение в квадрат даёт неравносильную систему, а значит не следствие; но именно оно приводит к системе-следствию: каждое решение первой системы остаётся решением второй.")},
  dadd=[("нельзя определить, не решив обе системы", "Ученик решил, что вывод о следствии возможен только после нахождения решений; но следствие определяется самим преобразованием: возведение в квадрат его даёт.")])
E("G11_TB_14_2_14_19_e", r"из $\log_{7}(x+y)+\log_{7}(x-y)=1$ следует $(x+y)(x-y)=7$, то есть $\log_{7}((x+y)(x-y))=1$: каждое решение первой системы является решением второй (обратное неверно, область шире); в ключе стояло «нет»",
  k="да",
  dnew={0: ("нет", "Ученик заметил, что $\\log_{7}((x+y)(x-y))$ определён шире суммы логарифмов, и решил, что второй системы нет среди следствий; но это лишь значит, что у второй системы могут появиться лишние решения, а каждое решение первой остаётся решением второй.")},
  dadd=[("да, но только при $x>y>0$", "Ученик верно понял, что вторая система следует из первой, но добавил лишнее условие $x>y>0$: оно уже входит в область определения первой системы, и ответ не меняется.")])
E("G11_TB_14_2_14_19_c", r"в учебнике $\frac{\sqrt{x}}{y}+\frac{\sqrt{y}}{x}=\frac{35}{36}$ (а не $\sqrt{\frac{x}{y}}+\sqrt{\frac{y}{x}}$); умножение на $xy\ne0$ даёт $x\sqrt{x}+y\sqrt{y}=\frac{35}{36}xy$ — вторая система следует из первой",
  q=r"Является ли вторая система следствием первой системы: в) $\begin{cases} \dfrac{\sqrt{x}}{y}+\dfrac{\sqrt{y}}{x}=\dfrac{35}{36}, \\ \sqrt{x}+\sqrt{y}=y-x \end{cases}$ и $\begin{cases} x\sqrt{x}+y\sqrt{y}=\dfrac{35}{36}xy, \\ \sqrt{x}+\sqrt{y}=y-x \end{cases}$",
  dnew={0: ("нет", "Ученик решил, что умножение на $xy$ меняет множество решений; но на области определения ($x>0$, $y>0$) умножение на $xy\\ne0$ равносильно, поэтому вторая система следует из первой."),
        1: ("нет, только при $x=y$", "Ученик проверил только случай $x=y$, получил противоречие и решил, что связь между системами так не проверить; вывод нужно делать для всех решений первой системы."),
        2: ("да, но только если $x>0$ и $y>0$", "Ученик верно понял, что первое уравнение умножают на $xy$, но добавил лишнее условие: область определения $x>0$, $y>0$ уже задана первой системой, поэтому ответ просто «да».")})
